import numpy as np,collections
def tab(rows,keys):return '| '+' | '.join(keys)+' |\n|'+'|'.join(['---']*len(keys))+'|\n'+'\n'.join('| '+' | '.join(str(r.get(k,'')) for k in keys)+' |' for r in rows)
def main():
 assert rd(H135/'SCALAR_AUDIT.json')['status']=='PASS';Q=H135/'scores_attempt001';agg=rd(Q/'AGGREGATE_ROWS.json');meth=rd(Q/'ALL_METHOD_ROWS.json');paired=rd(Q/'ALL_PAIRED_ROWS.json');tails=rd(Q/'ALL_CHANGED_CASES_PRIVATE.json');rows=[r for p in Q.glob('*_ALL_ROWS_PRIVATE.json') for r in rd(p)];decision=rd(H135/'DECISION.json');audit=rd(H135/'NATIVE_AUDIT.json');v={r['arm']:r for r in agg if r['aggregation']=='design_weighted' and r['group']=='all_six_equal'};w={r['arm']:r for r in agg if r['aggregation']=='raw' and r['group']=='all_six_equal'}
 focus=['original_source','legacy_zero_F','legacy_R134','intact_live_A','intact_live_F','AB_mean','direct_A','tta_A','wrong_A','direct_F','tta_F','wrong_F'];metricrows=[{'arm':k,'weighted_mIoU':f'{v[k]["mIoU_percent"]:.6f}','raw_mIoU':f'{w[k]["mIoU_percent"]:.6f}','weighted_Acc25':f'{v[k]["Acc25_percent"]:.6f}','weighted_Acc50':f'{v[k]["Acc50_percent"]:.6f}'} for k in focus];factor=[]
 for state in ['intact','reset']:
  for reader in ['live','fixed']:
   factor.append({'state':state,'reader':reader,'A_mIoU':f'{v[state+"_"+reader+"_A"]["mIoU_percent"]:.6f}','FAB_mIoU':f'{v[state+"_"+reader+"_F"]["mIoU_percent"]:.6f}'})
 links=[('reset_only_A','reset_live_A','intact_live_A'),('fixed_only_A','intact_fixed_A','intact_live_A'),('fixed_after_reset_A','reset_fixed_A','reset_live_A'),('reset_under_fixed_A','reset_fixed_A','intact_fixed_A'),('AB_fusion_intact_live','intact_live_F','intact_live_A'),('AB_fusion_reset_fixed','reset_fixed_F','reset_fixed_A'),('joint_reset_fixed_A','reset_fixed_A','intact_live_A')];effects=[{'effect':tag,'gain_pp':v[m]['mIoU_percent']-v[c]['mIoU_percent']} for tag,m,c in links];joint=next(x['gain_pp'] for x in effects if x['effect']=='joint_reset_fixed_A');main1=next(x['gain_pp'] for x in effects if x['effect']=='reset_only_A');main2=next(x['gain_pp'] for x in effects if x['effect']=='fixed_only_A');interaction=joint-main1-main2
 counts={'n':len(rows),'has_B':sum(r['has_B'] for r in rows),'no_B':sum(not r['has_B'] for r in rows),'active':sum(r['active'] for r in rows),'partial_active':sum(r['partial_active'] for r in rows),'pair_active':sum(r['pair_count']>0 for r in rows),'pairs':sum(r['pair_count'] for r in rows),'content_groups':len({r['content_group_PRIVATE'] for r in rows}),'frame_paths':len({r['frame_PRIVATE'] for r in rows}),'descriptions':len({r['id_PRIVATE'] for r in rows})};comparisons=[]
 for m,c in [('tta_A','intact_live_A'),('tta_A','direct_A'),('tta_A','wrong_A'),('tta_A','legacy_R134'),('tta_F','intact_live_F'),('tta_F','intact_live_A'),('tta_F','direct_F')]:
  pp=[r for r in paired if r['aggregation']=='design_weighted' and r['method']==m and r['control']==c];comparisons.append({'method':m,'control':c,'gain_pp':v[m]['mIoU_percent']-v[c]['mIoU_percent'],'better':sum(r['better'] for r in pp),'worse':sum(r['worse'] for r in pp),'query_changed':sum(r['query_changed'] for r in pp),'largest_positive_contribution_pp':max(r['largest_positive_contribution_pp'] for r in pp)})
 groupdiagnostics=[]
 for m,c in [('tta_A','intact_live_A'),('tta_F','intact_live_F')]:
  ss=[r for r in tails if r['method']==m and r['control']==c];groupdiagnostics.append({'method':m,'control':c,'changed':len(ss),'same_geometric_group':sum(r['same_geometric_group'] for r in ss),'higher_candidate_outside_C':sum(not (r['method_in_C'] if r['delta_IoU']>0 else r['control_in_C']) for r in ss),'good_C_but_wrong_final':sum(r['C_has_good'] and r['IoUs'][m]<=.25 for r in rows if r['active'])})
 costs=[]
 for src,tgt in sorted({(r['source'],r['target']) for r in rows}):
  records=[rd(p) for p in (B135/'formal'/f'{src}_to_{tgt}'/'fit_records_PRIVATE').glob('*.json')];costs.append({'source':src,'target':tgt,'n':len(records),'prepare_seconds':sum(r['seconds'] for r in records),'all_four_fit_seconds':sum(r['fit_seconds'] for r in records),'note':'measured matrix wallcost, includes controls/I/O; source model loading excluded'})
 dump(H135/'SUMMARY.json',{'counts':counts,'factorial_effects':effects,'reset_fixed_A_interaction_pp':interaction,'comparisons':comparisons,'group_diagnostics':groupdiagnostics,'costs':costs})
 lines=['# R135 — intact initialization and live complete readout repair','','## Decision','','Engineering restoration: accepted. Full source-prepared A is reproduced for all1798 inputs, and every repaired no-B endpoint returns complete Frozen-A. Only pointUp4896 changes during adaptation; source-trained gates, RGB adapters, match and competition weights remain intact.','',f'TTA development candidate retained: **{decision["TTA_development_candidate_retained"]}**. Primary was fixed as tta_A before new predictions or scoring. Alternative F output is diagnostic and is not promoted by selecting the best target score. Registered working version: '+decision['current_working_version']+'.','','## Fixed scope and validity','','Same1798 exposed R131 inputs, all six source→target directions, original A256 boxes and original registered B. No source retraining, new expert, new B selection, new loss family, or FINAL. Every prediction was sealed and independently CPU audited before cached fixed-box IoUs. Existing target exposure means this is controlled development, not independent validation.','',json.dumps(counts,indent=2),'','The source-trained adapter Down/Up, gate_P/gate_I/late, RGB path and full competition are restored exactly. Runtime uses live hidden/text/local/own/relationship reads, live late RGB delta and live competition residual. A route is regenerated from intact frozen A then fixed across B/F and updates; no query identity is transferred across descriptions. The source adapted-point output, not raw P, anchors feature keep so zero-step keep is exactly0.','', '## Factorial zero-update decomposition','',tab(factor,['state','reader','A_mIoU','FAB_mIoU']),'','reset means source Up weight/bias and gate_P cleared as in the legacy initializer. fixed means legacy fixed source-A late/R residual with live new h/u; live means complete recomputed source-prepared readout. This2×2×2 separates initialization, readout and A/B fusion rather than assigning their joint effect to one component.','',tab([{'effect':r['effect'],'gain_pp':f'{r["gain_pp"]:.6f}'} for r in effects],['effect','gain_pp']),'',f'Reset×fixed-reader interaction on A: {interaction:.6f} pp. Main effects should not be summed without this interaction.','', '## Overall task results','',tab(metricrows,['arm','weighted_mIoU','raw_mIoU','weighted_Acc25','weighted_Acc50']),'','Design-weighted is the equal-six-direction mean after original within-direction content-group sampling weights. Raw is the equal-six-direction mean without those sampling weights. Acc thresholds use strict >.25 and >.5.','',tab([{**r,'gain_pp':f'{r["gain_pp"]:.6f}','largest_positive_contribution_pp':f'{r["largest_positive_contribution_pp"]:.6f}'} for r in comparisons],['method','control','gain_pp','better','worse','query_changed','largest_positive_contribution_pp']),'','## Six-direction results','',tab([{'direction':r['source']+'→'+r['target'],'arm':r['arm'],'mIoU':f'{r["mIoU_percent"]:.6f}','Acc25':f'{r["Acc25_percent"]:.6f}','Acc50':f'{r["Acc50_percent"]:.6f}'} for r in meth if r['aggregation']=='design_weighted' and r['arm'] in ['intact_live_A','intact_live_F','legacy_R134','direct_A','tta_A','wrong_A','tta_F']],['direction','arm','mIoU','Acc25','Acc50']),'','## Reconnecting R134 without conflating it with the repair','','Original rho0/3steps/Armijo9 and weights1 remain. Log-gap kappa2.742430260548657 is held fixed. Supported groups and registration thresholds are unchanged. Teacher probabilities and the resulting C/pair evidence are recomputed through the restored full source model, frozen before fitting. This necessarily changes labels compared with legacy R134 and is disclosed as a complete-path port, not an isolated parameter-reset effect. The inherited kappa was calibrated under the old foundation reader and pooled source-own labels; no fresh reader-specific calibration is claimed.','','The original R134 pair mechanism detects AB-agreed order reversed by F_AB, and that same frozen pair set is shared by A and F student arms. In A it can start satisfied and act during later partial-label changes; no alternative A-derived pair scheme is substituted. Partial+exact group-score constrained projection is the no-update direct control. Wrong-pair controls preserve S,C, multiplicity bins, graph and margins, but not initial hinge or semantic correctness; with no effective permuted pairs the correct result is reused. They are not a full wrong-partial-label control.','','No B means no adaptation or fusion: return complete source-prepared Frozen-A. Rows with B but no qualified task retain their own complete zero-step output; F is only an alternative diagnostic. S/C supervise the loss and are not hard final-output filters.','','## Good/bad cases and component limits','',tab(groupdiagnostics,['method','control','changed','same_geometric_group','higher_candidate_outside_C','good_C_but_wrong_final']),'','All positive and negative task changes are exported with anonymous frame/content/scene clusters, compared with own frozen, same-information direct/wrong and legacy R134. Higher-IoU is a box-quality proxy, not human-verified instance identity. Same geometric group may contain near-duplicate boxes; different groups do not certify different objects. No raw images/GT were opened for semantic relabeling. Whole-denominator no-B/B contributions and per-scene results are included; repeated physical observations are not independent scenes, and the single Drone recording does not support a scene-level population CI.','','## Audit and cost','',json.dumps(audit,indent=2),'',tab(costs,['source','target','n','prepare_seconds','all_four_fit_seconds']),'','CPU audit independently rebuilds native matching and full competition from saved live features and frozen source weights, checks source A equivalence, source-adapter+delta feature reconstruction, three-step/Armijo traces, objectives, frozen labels, exact direct projection KKT and all no-B fallbacks. Full decoder gradients are not independently CPU regenerated; engineering finite differences test their direction. Failed engineering/bookkeeping attempts and the premature absent-seal CPU audit are retained, with no target GT read and no result selection.','','Public payload excludes original descriptions, scene IDs, frame IDs, media, coordinates, features, weights and third-party code. Source checkpoints/base fingerprints are unchanged. No automatic sweep or further experiment is queued.']
 (H135/'REPORT.md').write_text('\n'.join(lines)+'\n');print({'decision':decision['current_working_version'],'counts':counts,'factorial_effects':effects,'comparisons':comparisons},flush=True)
